def transform(grid):
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    other = [v for v in counts if v != background]
    if not other:
        return [row[:] for row in grid]
    signal = max(other, key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Recolor the continuation of any row containing the pattern color.
    for r, row in enumerate(grid):
        positions = [c for c, value in enumerate(row) if value == signal]
        if not positions:
            continue
        last = positions[-1]
        # Continuation follows the same pattern as the row's non-background
        # cells, using the pattern rows above as a mask when available.
        template = None
        for rr in range(r - 1, -1, -1):
            if any(v == signal for v in grid[rr]):
                template = grid[rr]
                break
        if template is None:
            for c in range(last + 1, len(row)):
                if row[c] == background:
                    out[r][c] = 1
        else:
            for c in range(last + 1, len(row)):
                if row[c] == background and template[c] == signal:
                    out[r][c] = 1

    return out
