    h, w = len(grid), len(grid[0])

    for r, row in enumerate(grid):
        # Find a two-color alternating run that reaches near the row's end.
        colors = set(row)
        if len(colors) != 2:
            continue
        a, b = tuple(colors)

        # Detect the alternating phase from the longest alternating segment.
        best_start = best_end = 0
        start = 0
        for c in range(1, w):
            if row[c] == row[c - 1]:
                if c - start > best_end - best_start:
                    best_start, best_end = start, c
                start = c
        if w - start > best_end - best_start:
            best_start, best_end = start, w

        if best_end - best_start < 4:
            continue

        phase = row[best_start]
        period = 2
        for c in range(best_end, w):
            expected = phase if (c - best_start) % period == 0 else (b if phase == a else a)
            if row[c] != expected:
                # Recolor the missing alternating cells in the trailing run.
                if row[c] == row[-1] and row[-1] != expected:
                    out[r][c] = 1
                else:
                    break

    return out
